use axum::{extract::State, Json};
use serde::Serialize;

use crate::state::AppState;

/// Health status response payload.
#[derive(Debug, Serialize)]
pub struct HealthResponse {
    /// Overall service status string ("ok").
    pub status: &'static str,
    /// Service name identifier.
    pub service: &'static str,
    /// Application name identifier.
    pub app: &'static str,
    /// Crate semantic version string.
    pub version: &'static str,
    /// Whether an active flight dataset is loaded in memory.
    pub has_flight_data: bool,
    /// Total count of telemetry points currently loaded.
    pub point_count: usize,
    /// Server uptime in seconds.
    pub uptime_secs: u64,
    /// Server uptime in seconds (alias).
    pub uptime_seconds: u64,
}

/// Handler for `GET /api/v1/health`.
pub async fn health_check(State(state): State<AppState>) -> Json<HealthResponse> {
    let (has_flight_data, point_count) = {
        let lock = state.dataset.read().await;
        match &*lock {
            Some(ds) => (true, ds.points.len()),
            None => (false, 0),
        }
    };

    let elapsed = state.start_time.elapsed().as_secs();

    Json(HealthResponse {
        status: "ok",
        service: "flightreader-server",
        app: "flightreader-server",
        version: env!("CARGO_PKG_VERSION"),
        has_flight_data,
        point_count,
        uptime_secs: elapsed,
        uptime_seconds: elapsed,
    })
}
